if(typeof require==='function'){var Constants=require('./constants');var Upgrade=require('./upgrade');}var LaserAimerUpgrade=Upgrade.subclass();LaserAimerUpgrade.fields({_activated:false,_weaponId:0,_length:0});LaserAimerUpgrade.classMethods({createInitialUpgradeState:function(id,playerId,weaponId,length){var fields={_activated:false,_weaponId:weaponId,_length:length};return Upgrade.createInitialUpgradeState(id,playerId,Constants.UPGRADE_TYPES.LASER_AIMER,JSON.stringify(fields));}});LaserAimerUpgrade.methods({update:function(deltaTime){if(!this._activated){var activeWeapon=this.roundModel.getActiveWeapon(this.playerId);if(activeWeapon&&activeWeapon.getId()===this._weaponId){this._activated=true;this._emitEvent(Upgrade._EVENTS.UPGRADE_ACTIVATED,this.id);}}},done:function(){if(this._activated){var activeWeapon=this.roundModel.getActiveWeapon(this.playerId);if(activeWeapon&&(activeWeapon.getField("fired")||activeWeapon.getId()!==this._weaponId)){return true;}}return false;}});if(typeof module==='object'){module.exports=LaserAimerUpgrade;}